void Mob::SetFeigned(bool in_feigned) {

	if (in_feigned)	{
		if (IsClient()) {
			if (RuleB(Character, FeignKillsPet)){
				SetPet(0);
			}
			CastToClient()->SetHorseId(0);
		}
		entity_list.ClearFeignAggro(this);
		forget_timer.Start(FeignMemoryDuration);
	}
	else {
		forget_timer.Disable();
	}
	feigned = in_feigned;
}

